definitions.select:
SELECT ?root ?basis ?flavour ?relation ?status ?edge WHERE {
{ ?root <urn:mara:relation:satisfies> ?basis . BIND(<urn:mara:relation:satisfies> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
UNION { ?root <urn:mara:relation:decomposes> ?basis . BIND(<urn:mara:relation:decomposes> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:decomposes> . }
UNION { ?root <urn:mara:relation:derives_from> ?basis . BIND(<urn:mara:relation:derives_from> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:derives_from> . }
UNION { ?basis <urn:mara:relation:justifies> ?root . BIND(<urn:mara:relation:justifies> AS ?relation) ?edge <urn:mara:query:source> ?basis ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:justifies> . }
?basis a ?flavour ; <urn:mara:field:status> ?status .
}

SELECT ?root ?basis ?flavour ?relation ?status ?edge WHERE {
{ ?root <urn:mara:relation:satisfies> ?basis . BIND(<urn:mara:relation:satisfies> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
UNION { ?root <urn:mara:relation:contributes_to> ?basis . BIND(<urn:mara:relation:contributes_to> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:contributes_to> . }
UNION { ?root <urn:mara:relation:decomposes> ?basis . BIND(<urn:mara:relation:decomposes> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:decomposes> . }
?basis a ?flavour ; <urn:mara:field:status> ?status .
}

SELECT ?root ?other ?status ?matched ?kind WHERE {
{ ?root <urn:mara:query:nfc-casefold:title> ?matched . ?other <urn:mara:query:nfc-casefold:title> ?matched . BIND("title/title" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:title> ?matched . ?other <urn:mara:query:nfc-casefold:field:aliases> ?matched . BIND("title/alias" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:field:aliases> ?matched . ?other <urn:mara:query:nfc-casefold:title> ?matched . BIND("alias/title" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:field:aliases> ?matched . ?other <urn:mara:query:nfc-casefold:field:aliases> ?matched . BIND("alias/alias" AS ?kind) }
?other a <urn:mara:flavour:term> ; <urn:mara:field:status> ?status . FILTER(!sameTerm(?root,?other))
}

SELECT ?root ?source_status ?relation ?target ?target_status ?class ?compatible ?edge WHERE {
VALUES (?relation ?class) { (<urn:mara:relation:satisfies> "strict") (<urn:mara:relation:contributes_to> "strict") (<urn:mara:relation:decomposes> "strict") (<urn:mara:relation:derives_from> "strict") (<urn:mara:relation:threatens> "strict") (<urn:mara:relation:mitigates> "strict") (<urn:mara:relation:accepts> "strict") (<urn:mara:relation:verifies> "strict") (<urn:mara:relation:validates> "strict") (<urn:mara:relation:exercises> "strict") (<urn:mara:relation:justifies> "developmental") (<urn:mara:relation:supports> "developmental") (<urn:mara:relation:supersedes> "replacement") }
?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?target ; <urn:mara:query:relation> ?relation .
?root <urn:mara:field:status> ?source_status . ?target <urn:mara:field:status> ?target_status .
BIND((sameTerm(?source_status,"draft") || sameTerm(?class,"developmental") || (sameTerm(?class,"strict") && (!sameTerm(?source_status,"accepted") || sameTerm(?target_status,"accepted"))) || (sameTerm(?class,"replacement") && sameTerm(?target_status,"retired") && (sameTerm(?source_status,"accepted") || sameTerm(?source_status,"retired")))) AS ?compatible)
}

SELECT ?root ?implementation ?design ?route ?implementation_edge ?design_edge WHERE {
{ ?implementation <urn:mara:relation:implements> ?root . BIND("direct" AS ?route) ?implementation_edge <urn:mara:query:source> ?implementation ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:implements> . }
UNION { ?root a <urn:mara:flavour:requirement> . ?design <urn:mara:relation:satisfies> ?root ; <urn:mara:field:status> "accepted" . ?implementation <urn:mara:relation:implements> ?design . BIND("design" AS ?route) ?implementation_edge <urn:mara:query:source> ?implementation ; <urn:mara:query:target> ?design ; <urn:mara:query:relation> <urn:mara:relation:implements> . ?design_edge <urn:mara:query:source> ?design ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
}

SELECT ?root ?likelihood ?consequence WHERE {
OPTIONAL { ?root <urn:mara:field:likelihood> ?likelihood } OPTIONAL { ?root <urn:mara:field:consequence> ?consequence }
}

SELECT ?root ?ancestor ?target ?kind ?status ?context_edge ?need_edge WHERE {
{ ?root (<urn:mara:relation:decomposes>|<urn:mara:relation:derives_from>)* ?ancestor . BIND(?ancestor AS ?target) BIND("requirement" AS ?kind) }
UNION { ?root (<urn:mara:relation:decomposes>|<urn:mara:relation:derives_from>)* ?ancestor . ?ancestor <urn:mara:relation:satisfies> ?target . ?target a <urn:mara:flavour:need> . BIND("need" AS ?kind)
?context_edge <urn:mara:query:source> ?ancestor ; <urn:mara:query:target> ?target ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
UNION { ?root (<urn:mara:relation:decomposes>|<urn:mara:relation:derives_from>)* ?ancestor . ?ancestor <urn:mara:relation:satisfies> ?need . ?need a <urn:mara:flavour:need> ; <urn:mara:relation:contributes_to> ?target . BIND("goal" AS ?kind)
?context_edge <urn:mara:query:source> ?need ; <urn:mara:query:target> ?target ; <urn:mara:query:relation> <urn:mara:relation:contributes_to> .
?need_edge <urn:mara:query:source> ?ancestor ; <urn:mara:query:target> ?need ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
?target <urn:mara:field:status> ?status .
}

SELECT ?root ?risk ?status ?target ?ancestor ?kind ?scope_support ?risk_edge WHERE {
?root <urn:mara:query:input:scope> ?scope_row .
?scope_row <urn:mara:query:column:scope:target> ?target .
?scope_row <urn:mara:query:column:scope:ancestor> ?ancestor .
?scope_row <urn:mara:query:column:scope:kind> ?kind .
?risk <urn:mara:relation:threatens> ?target ; <urn:mara:field:status> ?status . ?risk_edge <urn:mara:query:source> ?risk ; <urn:mara:query:target> ?target ; <urn:mara:query:relation> <urn:mara:relation:threatens> .
OPTIONAL { ?scope_row <urn:mara:query:column:scope:scope_support> ?scope_support }
}

SELECT ?root ?verification ?status ?candidate ?edge ?knowledge_complete WHERE {
?verification <urn:mara:relation:verifies> ?root ; <urn:mara:field:status> ?status . ?edge <urn:mara:query:source> ?verification ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:verifies> .
BIND((EXISTS { ?verification <urn:mara:field:methods> ?method } && (EXISTS { ?verification <urn:mara:relation:verifies> ?accepted_target . ?accepted_target <urn:mara:field:status> "accepted" }) && !(EXISTS { ?verification <urn:mara:relation:verifies> ?invalid_target . ?invalid_target <urn:mara:field:status> ?target_status . FILTER(!sameTerm(?target_status,"accepted")) })) AS ?knowledge_complete)
FILTER(sameTerm(?lifecycle,"") || sameTerm(?lifecycle,?status))
}

SELECT ?root ?validation ?status ?context ?edge ?knowledge_complete WHERE {
?validation <urn:mara:relation:validates> ?root ; <urn:mara:field:status> ?status . ?edge <urn:mara:query:source> ?validation ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:validates> .
BIND((EXISTS { ?validation <urn:mara:field:methods> ?method } && (EXISTS { ?validation <urn:mara:relation:validates> ?accepted_target . ?accepted_target <urn:mara:field:status> "accepted" }) && !(EXISTS { ?validation <urn:mara:relation:validates> ?invalid_target . ?invalid_target <urn:mara:field:status> ?target_status . FILTER(!sameTerm(?target_status,"accepted")) } || EXISTS { ?validation <urn:mara:relation:exercises> ?invalid_target . ?invalid_target <urn:mara:field:status> ?target_status . FILTER(!sameTerm(?target_status,"accepted")) })) AS ?knowledge_complete)
FILTER(sameTerm(?lifecycle,"") || sameTerm(?lifecycle,?status))
}

SELECT ?root ?status ?basis_status ?verification_status ?basis_support ?verification_edge WHERE {
?root <urn:mara:field:status> ?status . OPTIONAL { ?root <urn:mara:query:input:basis> ?basis_row .
?basis_row <urn:mara:query:column:basis:status> ?basis_status . OPTIONAL { ?basis_row <urn:mara:query:column:basis:basis_support> ?basis_support } }
OPTIONAL { ?verification <urn:mara:relation:verifies> ?root ; <urn:mara:field:status> ?verification_status . ?verification_edge <urn:mara:query:source> ?verification ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:verifies> . }
}

SELECT ?root ?status ?basis_status ?verification_status ?basis_support WHERE {
?root <urn:mara:field:status> ?status . OPTIONAL { ?root <urn:mara:query:input:basis> ?basis_row .
?basis_row <urn:mara:query:column:basis:status> ?basis_status . OPTIONAL { ?basis_row <urn:mara:query:column:basis:basis_support> ?basis_support } }
}

SELECT ?root ?status WHERE {
?root <urn:mara:field:status> ?status .
}

SELECT ?root ?status ?collision_status ?repeats_title WHERE {
?root <urn:mara:field:status> ?status .
BIND(EXISTS { ?root <urn:mara:query:nfc-casefold:title> ?name ; <urn:mara:query:nfc-casefold:field:aliases> ?name } AS ?repeats_title)
OPTIONAL { ?root <urn:mara:query:input:collisions> ?collisions_row .
?collisions_row <urn:mara:query:column:collisions:status> ?collision_status . }
}

SELECT ?root ?risk ?status ?target ?likelihood ?consequence ?accepted ?risks_support WHERE {
?root <urn:mara:query:input:risks> ?risks_row .
?risks_row <urn:mara:query:column:risks:risk> ?risk .
?risks_row <urn:mara:query:column:risks:status> ?status .
?risks_row <urn:mara:query:column:risks:target> ?target .
FILTER(sameTerm(?status,"accepted"))
OPTIONAL { ?risk <urn:mara:field:likelihood> ?likelihood } OPTIONAL { ?risk <urn:mara:field:consequence> ?consequence }
BIND(EXISTS { ?decision <urn:mara:relation:accepts> ?risk ; <urn:mara:field:status> "accepted" } AS ?accepted)
OPTIONAL { ?risks_row <urn:mara:query:column:risks:risks_support> ?risks_support }
}

SELECT ?root ?risk ?level ?levels_support WHERE {
?root <urn:mara:query:input:levels> ?levels_row .
?levels_row <urn:mara:query:column:levels:risk> ?risk .
?levels_row <urn:mara:query:column:levels:status> ?status .
?levels_row <urn:mara:query:column:levels:level> ?level .
?levels_row <urn:mara:query:column:levels:accepted> ?accepted .
FILTER(sameTerm(?status,"accepted") && sameTerm(?level,"HIGH") && sameTerm(?accepted,false))
OPTIONAL { ?levels_row <urn:mara:query:column:levels:levels_support> ?levels_support }
}

SELECT ?root ?validation ?status ?context ?knowledge_complete WHERE {
BIND(?root AS ?validation) ?root <urn:mara:field:status> ?status .
BIND((EXISTS { ?root <urn:mara:field:methods> ?method } && (EXISTS { ?root <urn:mara:relation:validates> ?accepted_target . ?accepted_target <urn:mara:field:status> "accepted" }) && !(EXISTS { ?root <urn:mara:relation:validates> ?invalid_target . ?invalid_target <urn:mara:field:status> ?target_status . FILTER(!sameTerm(?target_status,"accepted")) } || EXISTS { ?root <urn:mara:relation:exercises> ?invalid_target . ?invalid_target <urn:mara:field:status> ?target_status . FILTER(!sameTerm(?target_status,"accepted")) })) AS ?knowledge_complete)
}

SELECT ?root ?status WHERE {
?root <urn:mara:field:status> ?status .
}

SELECT ?root ?implementation ?design ?route ?implementation_edge ?design_edge WHERE {
{ ?implementation <urn:mara:relation:implements> ?root . BIND("direct" AS ?route) ?implementation_edge <urn:mara:query:source> ?implementation ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:implements> . }
UNION { ?root a <urn:mara:flavour:requirement> . ?design <urn:mara:relation:satisfies> ?root ; <urn:mara:field:status> "accepted" . ?implementation <urn:mara:relation:implements> ?design . BIND("design" AS ?route) ?implementation_edge <urn:mara:query:source> ?implementation ; <urn:mara:query:target> ?design ; <urn:mara:query:relation> <urn:mara:relation:implements> . ?design_edge <urn:mara:query:source> ?design ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
}

SELECT ?root ?source_status ?relation ?target ?target_status ?class ?compatible ?edge WHERE {
?root <urn:mara:query:input:lifecycle> ?row .
?row <urn:mara:query:column:lifecycle:source_status> ?source_status .
?row <urn:mara:query:column:lifecycle:relation> ?relation .
?row <urn:mara:query:column:lifecycle:target> ?target .
?row <urn:mara:query:column:lifecycle:target_status> ?target_status .
?row <urn:mara:query:column:lifecycle:class> ?class .
?row <urn:mara:query:column:lifecycle:compatible> ?compatible .
OPTIONAL { ?row <urn:mara:query:column:lifecycle:edge> ?edge }
}

SELECT ?root ?compatible WHERE {
BIND(!EXISTS { ?root <urn:mara:relation:satisfies> ?target . FILTER(!EXISTS { ?target a <urn:mara:flavour:need> }) } AS ?compatible)
}

SELECT ?root ?state ?validation ?support ?facts WHERE {
{ ?root <urn:mara:query:input:records> ?records_row .
?records_row <urn:mara:query:column:records:status> ?status .
?records_row <urn:mara:query:column:records:applicable> ?applicable .
?records_row <urn:mara:query:column:records:knowledge_complete> ?knowledge_complete . FILTER(sameTerm(?status,"accepted") && sameTerm(?applicable,true) && sameTerm(?knowledge_complete,true)) ?records_row <urn:mara:query:column:records:result> ?state . }
UNION { ?root <urn:mara:query:input:records> ?records_row .
?records_row <urn:mara:query:column:records:status> ?status .
?records_row <urn:mara:query:column:records:applicable> ?applicable .
?records_row <urn:mara:query:column:records:knowledge_complete> ?knowledge_complete . FILTER(sameTerm(?status,"accepted") && !(sameTerm(?applicable,true) && sameTerm(?knowledge_complete,true))) BIND("PENDING" AS ?state) }
?records_row <urn:mara:query:column:records:validation> ?validation .
OPTIONAL { ?records_row <urn:mara:query:column:records:support> ?support }
OPTIONAL { ?records_row <urn:mara:query:column:records:facts> ?facts }
}

SELECT ?root ?validation ?status ?context ?result ?definition_revision ?applicable ?knowledge_complete ?summary ?validation_count ?support ?facts ?summary_facts WHERE {
?root <urn:mara:query:input:summary> ?summary_row .
?summary_row <urn:mara:query:column:summary:state> ?summary .
OPTIONAL { ?summary_row <urn:mara:query:column:summary:count> ?validation_count }
OPTIONAL { ?summary_row <urn:mara:query:column:summary:summary_facts> ?summary_facts }
OPTIONAL {
?root <urn:mara:query:input:records> ?records_row .
OPTIONAL { ?records_row <urn:mara:query:column:records:validation> ?validation }
OPTIONAL { ?records_row <urn:mara:query:column:records:status> ?status }
OPTIONAL { ?records_row <urn:mara:query:column:records:result> ?result }
OPTIONAL { ?records_row <urn:mara:query:column:records:definition_revision> ?definition_revision }
OPTIONAL { ?records_row <urn:mara:query:column:records:applicable> ?applicable }
OPTIONAL { ?records_row <urn:mara:query:column:records:knowledge_complete> ?knowledge_complete }
OPTIONAL { ?records_row <urn:mara:query:column:records:support> ?support }
OPTIONAL { ?records_row <urn:mara:query:column:records:facts> ?facts }
}
}
